package strom.fs2

import scala.util.Random
import scala.concurrent.duration.*
import cats.effect.{IO, Ref}
import cats.effect.unsafe.implicits.global
import _root_.fs2.{Chunk, Stream}

object FuzzSupport:
  final class Boom extends RuntimeException("boom")
  def ef(log: Ref[IO, Vector[String]], tag: String, x: Int): IO[Unit] = log.update(_ :+ s"$tag:$x")

/** Random fs2 operator chains (generated by project/FuzzGen.scala) with effects and failures:
 *  `.fused` must give exactly the plain stream's output and effect log; `.fusedPar(3)` its
 *  output. When the chain throws, all variants must fail with the same error. */
class FuzzSuite extends munit.FunSuite:
  type Mk = (Stream[IO, Int], Ref[IO, Vector[String]]) => Stream[IO, Int]
  /** Output (Right elements, then possibly the error message) and the effect log. */
  final case class Run(out: List[Either[String, Int]], log: Vector[String]):
    def failed: Boolean = out.lastOption.exists(_.isLeft)
    def elements: List[Int] = out.collect { case Right(x) => x }

  def input(r: Random): Stream[IO, Int] =
    val xs = Array.fill(r.nextInt(300))(r.nextInt(66) - 5)
    Stream.emits(xs.grouped(1 + r.nextInt(20)).map(c => if r.nextBoolean() then Chunk.array(c) else Chunk.from(c.toVector)).toSeq)
      .flatMap(Stream.chunk).covary[IO]

  def run(mk: Mk, seed: Long): Run =
    (for
      log <- Ref[IO].of(Vector.empty[String])
      out <- mk(input(Random(seed)), log).attempt.map(_.left.map(_.getMessage)).compile.toList
      l   <- log.get
    yield Run(out, l)).timeout(20.seconds).unsafeRunSync()

  /** Fails with the first position where `a` and `b` differ, and a little context. */
  def same[T](what: String, a: Seq[T], b: Seq[T], code: String): Unit =
    if a != b then
      val i = a.indices.find(i => i >= b.size || a(i) != b(i)).getOrElse(a.size)
      fail(s"$what differs at $i (fused ${a.size}, plain ${b.size})\n$code\nfused ${a.slice(i - 3, i + 4)}\nplain ${b.slice(i - 3, i + 4)}")

  var exactOnFailure = 0
  var failures = 0
  var lazier = 0

  for c <- FuzzCases.cases do
    test(s"case ${c.name}: ${c.code.take(100)}") {
      val r = Random(c.name.hashCode)
      for _ <- 0 until 12 do
        val seed = r.nextLong()
        val (p, f, par) = (run(c.plain, seed), run(c.fused, seed), run(c.par, seed))
        if !p.failed then
          same("output", f.out, p.out, c.code)
          same("effect log", f.log, p.log, c.code)
          same("fusedPar output", par.out, p.out, c.code)
        else
          // Plain code failed. Fused code evaluates lambdas only for the elements it needs, while
          // plain fs2 / ZIO map whole chunks at once: if the failing element lies past a `take`,
          // fused code can succeed. Otherwise both fail with the same error, and the elements
          // emitted before it may differ at chunk granularity (one is a prefix of the other).
          failures += 1
          for (v, name) <- List(f -> "fused", par -> "fusedPar") do
            if v.failed then assertEquals(v.out.last, p.out.last, s"$name: different error\n${c.code}")
            else lazier += 1
            val (a, b) = (v.elements, p.elements)
            assert(a.startsWith(b) || b.startsWith(a), s"$name: outputs diverge\n${c.code}\n$name $a\nplain $b")
          if f.failed && f.elements == p.elements then exactOnFailure += 1
    }

  override def afterAll(): Unit =
    println(s"fs2 fuzz: ${FuzzCases.cases.size} chains; on failure, fused output before the error was identical in $exactOnFailure/$failures runs; fused succeeded where plain failed (lazier) $lazier times")
